import pathlib,subprocess,json,hashlib,os,datetime,time
R=pathlib.Path(subprocess.check_output(['git','rev-parse','--show-toplevel'],text=True).strip());A=R/'projects/chirality-app-dev';V=pathlib.Path(__file__).resolve().parent;O=V/'closeout-01';O.mkdir(exist_ok=False)
keep=['PATH','HOME','TMPDIR','TMP','TEMP','LANG','LC_ALL','SHELL','USER','LOGNAME'];env={k:v for k,v in os.environ.items() if k in keep};env['PYTHONDONTWRITEBYTECODE']='1'
