def run(argv,cwd,label):
 start=now();t=time.monotonic();p=subprocess.run(argv,cwd=cwd,env=env,text=True,capture_output=True);(O/(label+'.output.json')).write_text(json.dumps({'stdout':p.stdout,'stderr':p.stderr},indent=2)+'\n');row={'id':label,'argv':argv,'cwd':str(cwd),'start':start,'end':now(),'duration_seconds':time.monotonic()-t,'exit_code':p.returncode};rows.append(row);(O/'commands.json').write_text(json.dumps(rows,indent=2)+'\n');print(json.dumps(row),flush=True)
run(['python3','--version'],R,'python-version');run(['git','rev-parse','HEAD'],R,'head')
paths=subprocess.check_output(['git','ls-files','-z','AGENTS.md','agents','docs','skills','tools','runtime','projects/chirality-app-dev/AGENTS.md','projects/chirality-app-dev/software-workflow.json','projects/chirality-app-dev/loop','projects/chirality-app-dev/execution/_Scripts'],cwd=R).decode().split('\0');inputs={p:h(R/p) for p in sorted(set(paths)) if p and (R/p).is_file()};(O/'input-inventory.json').write_text(json.dumps(inputs,indent=2)+'\n')
