run(['python3','tools/validation/validate_app_dev_loop_receipts.py','--repo-root','.'],R,'predecessor-receipt-validator')
run(['python3','execution/_Scripts/app_hold.py','scan','--require-register-match'],A,'app-hold-integrity')
run(['python3','execution/_Scripts/app_hold.py','check','--operation','reliance','--entry-path','APP_LOOP_SHELL_2026-09-05:GLOBAL_VALIDATION','--target','DEL-02-03'],A,'app-hold-reliance')
drift=[p for p,s in inputs.items() if not (R/p).is_file() or h(R/p)!=s];source_drift=[x['path'] for x in files if h(R/x['path'])!=x['sha256']];(O/'input-stability.json').write_text(json.dumps({'input_drift':drift,'source_drift':source_drift,'input_count':len(inputs)},indent=2)+'\n');(O/'return.json').write_text(json.dumps({'verdict':'PASS' if not drift and not source_drift and all(x['exit_code']==0 for x in rows) else 'FAIL','final_receipt_after_append':'OWED','full_staged_check':'OWED CHANGE-owned','no_frontend_process_checks':True},indent=2)+'\n');(O/'evidence-sha256.json').write_text(json.dumps({str(p.relative_to(O)):h(p) for p in sorted(O.iterdir()) if p.is_file()},indent=2)+'\n')
